  "concept": "một khoảnh khắc tĩnh lặng gợi cảm giác như được hồi tưởng hơn là chụp ảnh",
  "subject": {
    "type": "chàng trai trẻ",
    "age": "đầu 20",
    "presence": "tinh tế, gần như không được chú ý trong khung hình",
